/* ---------- actions (merged into ACT by main.js) ---------- */
const SRF_ACT = {
  srfRole: t => { SRF.S.role = t.value; SRF.landing(); srfAfter(); },
  srfSelAll: t => { const S = SRF.S, on = t.dataset.v === '1'; if (t.dataset.k === 'paysel') SRF.scopeLines().filter(l => l.vstatus === 'Approved' && l.pstatus === 'Pending HR Processing' && !SRF.subOf(l.sub).locked).forEach(l => S.pay.sel[l.empId] = on); else { const d = S.draft; SRF.draftAdms(d).filter(a => !SRF.elig(a)).forEach(a => { d.include[a.enrol] = on; if (on && !d.assign[a.enrol]) d.assign[a.enrol] = SRF.defaultAssign(a); }); } rerender(); },
  srfDashF: t => { App.ui.srfDashF = App.ui.srfDashF === t.dataset.k ? '' : t.dataset.k; rerender(); },
  srfDashClear: () => { App.ui.srfDashF = ''; App.ui.srfQ = ''; rerender(); },
  srfView: t => srfViewModal(t.dataset.k),
  srfOpenQ: t => { App.ui.srfSel = t.dataset.k; App.ui.srfVTab = 'pending'; go('srf_verification'); },
  srfVTab: t => { App.ui.srfVTab = t.dataset.k; App.ui.srfSel = null; SRF.S.acc = { sel: null, remark: '', checked: {} }; rerender(); },
  srfSel: t => { App.ui.srfSel = t.dataset.k; SRF.S.acc.checked = {}; rerender(); },
  srfDecide: t => { const S = SRF.S; S.acc.sel = App.ui.srfSel; SRF.decide(t.dataset.v); srfAfter(); },
  srfPTab: t => { App.ui.srfPTab = t.dataset.k; rerender(); },
  srfBatch: () => { const S = SRF.S; S.hr.checked = {}; Object.keys(S.pay.sel).filter(k => S.pay.sel[k]).forEach(k => SRF.scopeLines().filter(l => l.empId === k && l.pstatus === 'Pending HR Processing').forEach(l => S.hr.checked[l.id] = true)); S.pay.sel = {}; SRF.createBatch(); if (S.batches.length) App.ui.srfPTab = 'batches'; srfAfter(); },
  srfHold: () => { const S = SRF.S; if (!S.hr.reason.trim()) return toast('Type a reason to hold first.', 'bad'); Object.keys(S.pay.sel).filter(k => S.pay.sel[k]).forEach(k => SRF.scopeLines().filter(l => l.empId === k && l.pstatus === 'Pending HR Processing').forEach(l => SRF.holdLine(l.id))); S.pay.sel = {}; srfAfter(); },
  srfRelease: t => { SRF.scopeLines().filter(l => l.empId === t.dataset.k && l.pstatus === 'On Hold').forEach(l => SRF.releaseLine(l.id)); srfAfter(); },
  srfInclude: t => { SRF.includePayroll(t.dataset.k); srfAfter(); },
  srfPaid: t => { const ref = t.dataset.k, b = SRF.S.batches.find(x => x.ref === ref); if (!b) return; let tmp = null; if (b.method !== 'Payroll') { const f = document.getElementById('srfProof-' + ref); tmp = document.createElement('input'); tmp.type = 'file'; tmp.id = 'proof-' + ref; try { if (f && f.files.length) tmp.files = f.files; } catch (e) { } SRF_ROOT.appendChild(tmp); } try { SRF.markPaid(ref); } finally { if (tmp) tmp.remove(); } srfAfter(); },
  srfRev: t => { SRF.requestReversal(t.dataset.k); srfAfter(); },
  srfRevOk: t => { SRF.approveRev(t.dataset.k); srfAfter(); },
  srfRecovered: t => { SRF.recovered(t.dataset.k); srfAfter(); },
  srfRep: t => { App.ui.srfRep = t.dataset.k; rerender(); },
  srfWTab: t => { App.ui.srfWTab = t.dataset.k; App.ui.srfDone = ''; rerender(); },
  srfNew: () => { const S = SRF.S; const own = SRF.principalBranches(); S.draft = SRF.newDraft(own[0] || ''); App.ui.srfDone = ''; App.ui.srfWTab = 'new'; rerender(); },
  srfDraftOpen: t => { const S = SRF.S, x = S.drafts.find(y => y.id === t.dataset.k && y.by === S.uid); if (!x) return; S.draft = SRF.clone(x.d); App.ui.srfDone = ''; App.ui.srfWTab = 'new'; go('srf_submission'); },
  srfSaveDraft: () => { const S = SRF.S; if (!SRF.can('submission', 'Create')) return toast('Your role cannot save SRF drafts.', 'bad'); const d = S.draft, idd = d.draftId || ('D' + (S.drafts.length + 1 + S.subs.length)); S.drafts = S.drafts.filter(x => x.id !== idd); d.draftId = idd; S.drafts.push({ id: idd, by: S.uid, at: SRF.TODAY, d: SRF.clone(d) }); SRF.log('Save draft', 'Draft ' + idd, SRF.BR[d.branch] + ', ' + Object.values(d.include).filter(Boolean).length + ' admissions'); toast('Draft saved. Continue it from the dashboard or My requests.'); srfAfter(); },
  srfSubmit: () => { const S = SRF.S, n0 = S.subs.length; SRF.submit(S.draft); if (S.subs.length > n0) { App.ui.srfDone = S.subs.at(-1).ref; S.draft = SRF.newDraft(S.draft.branch); } srfAfter(); },
  srfRevise: t => { const S = SRF.S, s = SRF.subOf(t.dataset.k); if (!s) return; if (!SRF.can('submission', 'Edit')) return toast('Your role cannot revise SRF requests.', 'bad'); if (s.status !== 'Returned to Principal') return toast('Only a request returned for correction can be changed.', 'bad'); if (S.subs.some(y => y.revOf === s.id)) return toast(s.ref + ' has already been resubmitted.', 'bad'); const d = SRF.newDraft(s.branch); d.revOf = s.id; d.remark = 'Revision: ' + (s.verRemark || ''); d.include = {}; s.adms.forEach(x => { d.include[x.enrol] = true; const as = {}; x.lines.forEach(l => (as[l.role] = as[l.role] || []).push(l.empId)); d.assign[x.enrol] = Object.assign(SRF.defaultAssign(SRF.adm(x.enrol)), as); }); S.draft = d; App.ui.srfWTab = 'new'; App.ui.srfDone = ''; rerender(); },
  srfAsgRm: t => { const [en, role, id] = t.dataset.k.split('|'), d = SRF.S.draft; if (!d.assign[en]) return; d.assign[en][role] = (d.assign[en][role] || []).filter(x => x !== id); rerender(); },
  /* change / input events from the native SRF pages */
  srfChange: t => { const S = SRF.S, k = t.dataset.k, id = t.dataset.id;
    if (k === 'acc') { S.acc.checked[id] = t.checked; return; }
    if (k === 'method') { S.hr.method = t.value; rerender(); return; }
    if (k === 'paysel') { if (id === '*') { SRF.scopeLines().filter(l => l.vstatus === 'Approved' && l.pstatus === 'Pending HR Processing' && !SRF.subOf(l.sub).locked).forEach(l => S.pay.sel[l.empId] = t.checked); } else S.pay.sel[id] = t.checked; rerender(); return; }
    if (k === 'inc') { const d = S.draft, el = SRF.draftAdms(d).filter(a => !SRF.elig(a)); if (id === '*') el.forEach(a => { d.include[a.enrol] = t.checked; if (t.checked && !d.assign[a.enrol]) d.assign[a.enrol] = SRF.defaultAssign(a); }); else { d.include[id] = t.checked; const a = el.find(x => x.enrol === id); if (t.checked && a && !d.assign[id]) d.assign[id] = SRF.defaultAssign(a); } rerender(); return; }
    if (k === 'draft:branch') { S.draft = SRF.newDraft(t.value); rerender(); return; }
    if (k.startsWith('asg:')) { const [en, role] = k.slice(4).split('|'), d = S.draft; if (!t.value) return; d.assign[en] = d.assign[en] || {}; d.assign[en][role] = (d.assign[en][role] || []).concat([t.value]); rerender(); return; }
    if (k.startsWith('rf:')) { S.rf = S.rf || {}; S.rf[k.slice(3)] = t.value; rerender(); return; }
  },
  srfInput: t => { const S = SRF.S, k = t.dataset.k;
    if (k === 'accRemark') { S.acc.remark = t.value; return; }
    if (k === 'hrReason') { S.hr.reason = t.value; return; }
    if (k === 'period') { S.hr.pd[SRF.ptype()] = t.value; return; }
    if (k.startsWith('ref:')) { S.hr.ref[k.slice(4)] = t.value; return; }
    if (k === 'draft:remark') { S.draft.remark = t.value; return; }
    if (k === 'draft:from' || k === 'draft:to') { if (!t.value) return; S.draft[k.slice(6)] = t.value; clearTimeout(SRF_ACT._t); SRF_ACT._t = setTimeout(rerender, 400); return; }
    if (k.startsWith('rf:')) { S.rf = S.rf || {}; S.rf[k.slice(3)] = t.value; clearTimeout(SRF_ACT._t); SRF_ACT._t = setTimeout(rerender, 400); return; }
  }
};

/* ---------- SRF system admin: Regional & Zonal Director mapping (native card above the embedded console) ---------- */
function srfDirectorCard() {
  const ed = can('admin_mapping', 'Manage branch mapping') || can('admin_mapping', 'Edit') || App.user.role === 'System Admin';
  const hd = App.ui.srfDirTab || 'zd', role = hd === 'zd' ? 'Zonal Director' : 'Regional Director';
  const S = SRF.S, srfIds = new Set(Object.keys(SRF.BR));
  const rows = users().filter(u => u.role === role && u.status === 'Active').map(u => { const areas = dirAreas(u, hd), brs = DATA.branches.filter(b => !b.closed && areas.includes(hd === 'zd' ? b.zone : b.region)), sch = brs.filter(b => srfIds.has(b.id)), su = S.users.find(x => x.id === u.id); return { u, areas, area: areas.join(', '), brs, sch, su }; }).sort((a, b) => a.area.localeCompare(b.area));
  const vacant = [...new Set(DATA.branches.filter(b => !b.closed && srfIds.has(b.id)).map(b => hd === 'zd' ? b.zone : b.region))].filter(a => !rows.some(r => r.areas.includes(a)));
  const t = table('srfDirs', [{ h: role, k: r => `${esc(pName(r.u))}<div class="small muted">${esc(r.u.email || '')}</div>`, t: 'html', x: r => pName(r.u) }, { h: hd === 'zd' ? 'Zone' : 'Region', k: r => r.area || '<span class="muted">Not assigned</span>', t: 'html', x: r => r.area }, { h: 'Branches', k: r => r.brs.length, t: 'num' }, { h: 'Schools in SRF', k: r => r.sch.length, t: 'num' }, { h: 'Schools under this director', k: r => r.sch.map(b => esc(b.name)).join(', ') || '<span class="muted">None</span>', t: 'html', x: r => r.sch.map(b => b.name).join('; '), cls: 'wrap small', w: 320 }, { h: 'SRF role', k: r => r.su ? r.su.roles.join(' + ') : '—', t: 'text' }, { h: 'SRF access', k: r => r.su ? pill(r.su.status, r.su.status === 'Active' ? 'ok' : 'bad') : pill('No SRF login', 'warn'), t: 'html', x: r => r.su ? r.su.status : 'No SRF login' }, ...(ed ? [{ h: '', k: r => `<div class="btnstack"><button class="btn sm" data-act="dirEdit" data-k="${r.u.id}" data-v="${hd}">Edit</button><button class="btn sm" data-act="dirAdd" data-k="${r.u.id}" data-v="${hd}">Add branches</button><button class="btn sm danger" data-act="dirRemove" data-k="${r.u.id}" data-v="${hd}">Remove</button></div>`, t: 'html', noexp: true }] : [])], rows, { title: role + ' mapping (SRF)', empty: `No ${role}s yet.` });
  const tabs = `<div class="tabs">${[['zd', 'Zonal Directors'], ['rd', 'Regional Directors']].map(([k, l]) => `<button class="tab${k === hd ? ' on' : ''}" data-act="ui" data-k="srfDirTab" data-v="${k}">${l}</button>`).join('')}</div>`;
  const note = vacant.length ? `<div class="note warn">${hd === 'zd' ? 'Zones' : 'Regions'} with SRF schools but no ${role}: <b>${vacant.map(esc).join(', ')}</b>.</div>` : '';
  return card('Regional & Zonal Director mapping', tabs + note + t, { right: `${ed ? `<button class="btn primary sm" data-act="dirNew" data-v="${hd}">Add ${role}</button>` : ''}${exportBtns('srfDirs', 'srf', { label: false })}`, sub: 'Directors see the SRF requests, payments and reports of the schools in their zone or region (management view). The mapping is the organisation hierarchy, shared with every other module; changes here apply everywhere from the effective date.' });
}
const SRF_CENTRAL = [['User logins', 'admin_users', 'Users'], ['Principal–branch mapping', 'hierarchy', 'Hierarchy setup'], ['Academic years', 'settings', 'Targets & instalments → Academic years'], ['Submission access windows', 'sa_rules', 'Data access rules (SRF window per Principal)'], ['Role permissions', 'admin_roles', 'Roles & permissions'], ['System audit logs', 'audit', 'Audit log → SRF module audit'], ['Regional & Zonal Directors', 'hierarchy', 'Hierarchy setup']];
function srfCentralCard() { return card('Centralised administration', `<p class="small">SRF users, mappings, academic years, access windows, permissions and audit are managed with every other module in the Admin control centre. The SRF console below keeps only what is specific to the incentive scheme: HRMS employee–branch mapping, special-access grants and integration tests.</p><div class="tbl-wrap"><table class="tbl compact"><thead><tr><th>SRF setting</th><th>Managed centrally in</th></tr></thead><tbody>${SRF_CENTRAL.map(([a, r, l]) => `<tr><td>${esc(a)}</td><td><button class="linkish" data-act="go" data-r="${r}">${esc(l)}</button></td></tr>`).join('')}</tbody></table></div>`); }
{ const base = PAGES.srf_sysadmin; if (base) { base.title = 'SRF settings & mapping'; const r0 = base.render; base.render = function () { if (!srfOK()) return srfDeny(); return srfRoleStrip() + srfCentralCard() + srfDirectorCard() + r0.call(this); }; } }
